urlset:

  {{ site_url }}/
  {% if latest %}{{ latest.strftime('%Y-%m-%d') }}{% endif %}

{% for category in categories %}

  {{ site_url }}{{ url_for('main.category', slug=category.slug) }}

{% endfor %}
{% for article in articles %}

  {{ site_url }}{{ url_for('main.article', id=article.id) }}
  {% if article.created_at %}{{ article.created_at.strftime('%Y-%m-%d') }}{% endif %}

{% endfor %}
